<script setup>
import {ref,onMounted,computed} from 'vue'
import {Button,FormControl,ErrorMessage,Badge} from '@relay/ui'
import RelaySelect from './RelaySelect.vue'
import RemoteLinkField from './fields/RemoteLinkField.vue'
import {coreApi} from '../services/coreApi'
import {useTask} from '../composables/useTask'
const {busy,error,notice,run}=useTask(),rows=ref([]),next=ref(null),draft=ref(null),review=ref(''),saved=ref('')
const signature=d=>JSON.stringify([d?.title,d?.policy,d?.source_message,d?.instructions,d?.examples])
const dirty=computed(()=>signature(draft.value)!==saved.value)
const policyField={label:'Policy',kind:'policy',method:'automation.settings.references'},sourceField={label:'Source message',kind:'source_message',method:'automation.settings.references'}
const blank=()=>({message:'',expected:{category:'Query',brief:'Expected support outcome',create_ticket:false,reply:null,handoff:true,create_report:false}})
async function load(after=null){const result=await coreApi('learning.service.directory',{after});rows.value=result.items;next.value=result.next}
function create(){draft.value={title:'',policy:'',source_message:'',instructions:'',examples:[blank(),blank(),blank()],evaluations:[]};review.value=''}
async function open(name){const result=await coreApi('learning.service.read',{name});result.examples=typeof result.examples==='string'?JSON.parse(result.examples):result.examples;draft.value=result;saved.value=signature(result);review.value=''}
async function save(){const d=draft.value,result=await coreApi('learning.service.save',{name:d.name||null,title:d.title,policy:d.policy,source_message:d.source_message||null,instructions:d.instructions,examples:d.examples},true);await open(result.name);await load();notice.value='Procedure draft saved'}
async function suggest(){const result=await coreApi('learning.service.suggest',{policy:draft.value.policy,source_message:draft.value.source_message},true);draft.value.instructions=result.instructions;notice.value='AI suggestion added to the draft. Review it before saving.'}
async function evaluate(){await save();await coreApi('learning.service.evaluate',{name:draft.value.name},true);await open(draft.value.name);notice.value='Evaluation queued. Refresh to check its result.'}
async function publish(evaluation){await coreApi('learning.service.publish',{name:draft.value.name,evaluation,review_note:review.value},true);await open(draft.value.name);await load();notice.value='Reviewed procedure published and enabled on its policy'}
onMounted(()=>run(()=>load()))
</script>
<template><section class="page-body space-y-5"><div class="flex flex-wrap gap-3 items-center"><h2 class="text-xl font-semibold flex-1">Reviewed AI learning</h2><Button label="New procedure" :disabled="busy" @click="create"/></div><p class="text-sm">Turn support examples into reusable instructions. Test at least three expected outcomes, then review and publish a version. Drafts never affect live decisions.</p><ErrorMessage :message="error"/><p v-if="notice" role="status" class="text-sm">{{notice}}</p><div class="grid gap-5 lg:grid-cols-[280px_minmax(0,1fr)]"><aside class="workflow-card space-y-3"><button v-for="row in rows" :key="row.name" class="block text-left border-b py-3 w-full" :disabled="busy" @click="run(()=>open(row.name))"><strong class="block break-words">{{row.title}}</strong><span class="text-xs">{{row.published_version?'Published version available':'Draft'}}</span></button><p v-if="!rows.length" class="text-sm">No saved procedures.</p><Button v-if="next" label="Next procedures" :disabled="busy" @click="run(()=>load(next))"/></aside><form v-if="draft" class="workflow-card space-y-4 min-w-0" @submit.prevent="run(save)"><FormControl label="Procedure title" v-model="draft.title" required/><RemoteLinkField :field="{...policyField,readOnly:!!draft.name}" v-model="draft.policy"/><RemoteLinkField :field="sourceField" v-model="draft.source_message"/><Button label="Suggest from source" :disabled="busy||!draft.policy||!draft.source_message" @click="run(suggest)"/><FormControl label="Reviewed instructions" type="textarea" v-model="draft.instructions" required/><h3 class="font-semibold">Evaluation examples</h3><article v-for="(example,index) in draft.examples" :key="index" class="border rounded p-3 space-y-3"><FormControl :label="'Example '+(index+1)+' message'" type="textarea" v-model="example.message" required/><RelaySelect :label="'Example '+(index+1)+' category'" v-model="example.expected.category" :options="['Query','Payment evidence','Support','Other']"/><div class="flex flex-wrap gap-4"><label><input type="checkbox" v-model="example.expected.handoff"/> Human handoff</label><label><input type="checkbox" v-model="example.expected.create_ticket"/> Create ticket</label><label><input type="checkbox" v-model="example.expected.create_report"/> Create report</label></div><FormControl :label="'Example '+(index+1)+' approved reply ID (optional)'" :model-value="example.expected.reply||''" @update:model-value="example.expected.reply=$event||null"/></article><div class="flex flex-wrap gap-2"><Button label="Save procedure" type="submit" :disabled="busy"/><Button label="Evaluate draft" :disabled="busy" @click="run(evaluate)"/><Button v-if="draft.name" label="Refresh evaluations" :disabled="busy" @click="run(()=>open(draft.name))"/></div><section v-if="draft.evaluations.length" class="space-y-3"><h3 class="font-semibold">Evaluation and publication</h3><FormControl label="Human review evidence" type="textarea" v-model="review"/><article v-for="evaluation in draft.evaluations" :key="evaluation.name" class="border-t py-3 space-y-2"><Badge :label="evaluation.status"/><p class="text-xs break-words">{{evaluation.name}} · {{evaluation.reason}}</p><Button v-if="evaluation.status==='Passed'" label="Publish reviewed version" :disabled="busy||dirty||review.trim().length<10" @click="run(()=>publish(evaluation.name))"/></article></section></form></div></section></template>
